pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    if config.base_delay_ms == 0 {
        return 0;
    }

    let shift = attempt.saturating_sub(1);
    let raw = config
        .base_delay_ms
        .checked_shl(shift)
        .unwrap_or(u64::MAX);
    raw.min(config.max_delay_ms)
}

